-- SOLO LECTURA. Seleccione la base y ejecute cada bloque en la misma conexión.
-- Complementa sql/diagnostico-canecas-metadatos-auxiliar.sql (identidad,
-- visibilidad, SHOW CREATE y grants); no consulta registros de negocio.
-- contract:tablas
SELECT TABLE_NAME,TABLE_TYPE,ENGINE,TABLE_COLLATION,CREATE_OPTIONS
FROM information_schema.TABLES WHERE BINARY TABLE_SCHEMA=BINARY DATABASE()
AND BINARY TABLE_NAME IN (BINARY 'empresas',BINARY 'usuarios',BINARY 'canecas_productos',BINARY 'canecas_ubicaciones',BINARY 'canecas_saldos',BINARY 'canecas_compras',BINARY 'canecas_recepciones',BINARY 'canecas_movimientos') ORDER BY BINARY TABLE_NAME;
-- contract:columnas
SELECT TABLE_NAME,ORDINAL_POSITION,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,CHARACTER_SET_NAME,COLLATION_NAME,GENERATION_EXPRESSION,NUMERIC_PRECISION,NUMERIC_SCALE,DATETIME_PRECISION,CHARACTER_MAXIMUM_LENGTH
FROM information_schema.COLUMNS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE()
AND BINARY TABLE_NAME IN (BINARY 'empresas',BINARY 'usuarios',BINARY 'canecas_productos',BINARY 'canecas_ubicaciones',BINARY 'canecas_saldos',BINARY 'canecas_compras',BINARY 'canecas_recepciones',BINARY 'canecas_movimientos') ORDER BY BINARY TABLE_NAME,ORDINAL_POSITION;
-- contract:indices
SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME,SUB_PART,INDEX_TYPE,COLLATION,NULLABLE,IGNORED
FROM information_schema.STATISTICS WHERE BINARY TABLE_SCHEMA=BINARY DATABASE()
AND BINARY TABLE_NAME IN (BINARY 'empresas',BINARY 'usuarios',BINARY 'canecas_productos',BINARY 'canecas_ubicaciones',BINARY 'canecas_saldos',BINARY 'canecas_compras',BINARY 'canecas_recepciones',BINARY 'canecas_movimientos') ORDER BY BINARY TABLE_NAME,BINARY INDEX_NAME,SEQ_IN_INDEX;
-- contract:foraneas
SELECT k.TABLE_NAME,k.CONSTRAINT_NAME,k.ORDINAL_POSITION,k.POSITION_IN_UNIQUE_CONSTRAINT,k.COLUMN_NAME,k.REFERENCED_TABLE_SCHEMA,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,r.UPDATE_RULE,r.DELETE_RULE
FROM information_schema.KEY_COLUMN_USAGE k LEFT JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON BINARY r.CONSTRAINT_SCHEMA=BINARY k.CONSTRAINT_SCHEMA AND BINARY r.TABLE_NAME=BINARY k.TABLE_NAME AND BINARY r.CONSTRAINT_NAME=BINARY k.CONSTRAINT_NAME
WHERE BINARY k.TABLE_SCHEMA=BINARY DATABASE() AND k.REFERENCED_TABLE_NAME IS NOT NULL
AND BINARY k.TABLE_NAME IN (BINARY 'empresas',BINARY 'usuarios',BINARY 'canecas_productos',BINARY 'canecas_ubicaciones',BINARY 'canecas_saldos',BINARY 'canecas_compras',BINARY 'canecas_recepciones',BINARY 'canecas_movimientos') ORDER BY BINARY k.TABLE_NAME,BINARY k.CONSTRAINT_NAME,k.ORDINAL_POSITION;
-- contract:checks
SELECT t.TABLE_NAME,t.CONSTRAINT_NAME,c.CHECK_CLAUSE
FROM information_schema.TABLE_CONSTRAINTS t LEFT JOIN information_schema.CHECK_CONSTRAINTS c ON BINARY c.CONSTRAINT_SCHEMA=BINARY t.CONSTRAINT_SCHEMA AND BINARY c.TABLE_NAME=BINARY t.TABLE_NAME AND BINARY c.CONSTRAINT_NAME=BINARY t.CONSTRAINT_NAME
WHERE BINARY t.CONSTRAINT_SCHEMA=BINARY DATABASE() AND t.CONSTRAINT_TYPE='CHECK'
AND BINARY t.TABLE_NAME IN (BINARY 'empresas',BINARY 'usuarios',BINARY 'canecas_productos',BINARY 'canecas_ubicaciones',BINARY 'canecas_saldos',BINARY 'canecas_compras',BINARY 'canecas_recepciones',BINARY 'canecas_movimientos') ORDER BY BINARY t.TABLE_NAME,BINARY t.CONSTRAINT_NAME;
